window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5659bd9555085cb2"]={"versions": [{"id": "FIG-5659bd9555085cb2", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR Methodology Activity Diagram (SPEM-/UML-Profil der AUTOSAR-Methodik).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Prozessschritts <code>Define System Variants</code> innerhalb der Phase <em>System Configuration</em> der AUTOSAR Classic Platform (R4.3.1). Der Schritt dient der formalen Festlegung, Bindung und Konsolidierung von Produktlinien-Variabilitäten über Topologie, Signalrouting, SWC-Zuordnung und ECU-Konfigurationen hinweg vor dem <em>System Extract of System Description</em>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Aktivitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>System Engineer</code></strong> (Rolle): Verantwortlicher Entwickler/Rolle; führt die Aktivität aus (<code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li><strong><code>Define System Variants</code></strong> (Activity / Task): Zentraler Transformationsschritt zur Auflösung bzw. Deklaration von Systemvarianten.\n</li></ul>\n<h5 class=\"fig-section-h5\">Eingangsartefakte (<code>«input»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>Topology</code></strong> (Kardinalität <code>1</code>): Physikalische Vernetzung, Busse (CAN, LIN, FlexRay, Ethernet) und Cluster.\n</li><li><strong><code>System Description</code></strong> (Kardinalität <code>0..*</code>): Übergeordnete Gesamtsystembeschreibung (<code>ARPackage</code>-Container).\n</li><li><strong><code>System Description Root Element</code></strong>: Wurzelknoten des System-Modells (<code>SYSTEM</code>-Metaklasse).\n</li><li><strong><code>Complete ECU Description</code></strong> (Kardinalität <code>1..*</code>): Vollständige Baukasten-Beschreibungen aller im System beteiligten Steuergeräte.\n</li><li><strong><code>Mapping of Software Components to ECUs</code></strong>: Zuweisung von atomaren SWC-Prototypen auf spezifische ECUs (<code>SwcToEcuMapping</code>).\n</li><li><strong><code>Mapping of Software Components to Implementations</code></strong>: Zuordnung der logischen SWCs zu konkreten C-/Objektcode-Implementierungen (<code>SwcImplementation</code>).\n</li><li><strong><code>System Signal</code></strong> &amp; <strong><code>System Signal Group</code></strong>: Kommunikationsmatrix-Elemente im Systemkontext (Signale und strukturierte Signalverbünde).\n</li><li><strong><code>System Timing</code></strong>: Globale und lokale Timing-Constraints (z. B. Latenzen, Event-Triggering).\n</li></ul>\n<h5 class=\"fig-section-h5\">Ein-/Ausgangs- und Ergebnisartefakte (<code>«output»</code> / <code>«inoutput»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>System Constant Value Set</code></strong> (<code>«inoutput»</code>): Iterativ definierte Belegung von Systemkonstanten (<code>SwSystemconst</code>), die als Prädikate in Variantenbedingungen dienen.\n</li><li><strong><code>Postbuild Variant Set</code></strong> (<code>«inoutput»</code>): Spezifikation der zur Post-Build-Zeit (Ladezeit/Initialisierungszeit) auflösbaren Variantenkriterien (<code>PostBuildVariantCriterion</code>).\n</li><li><strong><code>Predefined Variant</code></strong> (<code>«output»</code>): Deklaration vordefinierter Konfigurationszustände für Pre-Compile-Varianten durch Bündelung spezifischer <code>SystemConstantValueSets</code>.\n</li><li><strong><code>Evaluated Variant Set</code></strong> (<code>«output»</code>): Konsistenzgeprüfter und ausgewerteter Variantensatz zur Ableitung konkreter System- und ECU-Extrakte.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Eingangs-Aggregation:</strong> Einlesen der Systembeschreibungs-Fragmente (Topologie, SWC-Mappings, Signale, Timing und ECU-Beschreibungen).\n</li><li><strong>Kriterien-Definition &amp; Iteration (<code>«inoutput»</code>):</strong>\n<ul class=\"fig-list\"><li>Festlegung bzw. Aktualisierung von <code>System Constant Value Sets</code> zur statischen Konditionierung (<code>bindingTime = codeGenerationTime / preCompileTime</code>).\n</li><li>Definition bzw. Abgleich von <code>Postbuild Variant Sets</code> für dynamische Konfigurationen (<code>bindingTime = postBuild / runtime</code>).\n</li></ul>\n</li><li><strong>Varianten-Kombination (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li>Instanziierung von <code>Predefined Variant</code>-Elementen, die Gruppen von Systemkonstanten-Werten referenzieren.\n</li><li>Generierung des <code>Evaluated Variant Set</code>: Formal verifizierter Zustand, in dem alle <code>VariationPoint</code>-Elemente (z. B. an Signalmappings, Ports oder Verbindungen) widerspruchsfrei gegen die definierten Kriterien evaluierbar sind.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Binding Times &amp; Codegenerierung:</strong>\n<ul class=\"fig-list\"><li><strong>Pre-Compile-Varianten (<code>Predefined Variant</code>):</strong> Schlagen direkt auf Präprozessor-Makros (<code>#if / #ifdef</code>) im generierten RTE- und BSW-Code durch. Inaktive Funktionszweige und SWC-Instanzen belegen weder Flash noch RAM.\n</li><li><strong>Post-Build-Varianten (<code>Postbuild Variant Set</code>):</strong> Führen zur Generierung von multiplen Konfigurationsstrukturen im ROM/Flash, die zur Laufzeit über Zeigerdeskriptoren (<code>EcuM_Init()</code>, <code>BswM</code>) basierend auf Codiersteckern, EEPROM-Parametern oder Bus-Nachrichten aktiviert werden.\n</li></ul>\n</li><li><strong>Einfluss auf Signal- und Port-Interfaces:</strong> Signal-Routings (<code>System Signal</code>, <code>System Signal Group</code>) und SWC-Mappings sind potentiell variabilitätsbehaftet. Werden Signale variante-abhängig getrennt, generiert der RTE-Generator unterschiedliche COM-PDU-Layouts und Signal-Puffer.\n</li><li><strong>BSW- &amp; Treiber-Konfiguration:</strong> Der resultierende <code>Evaluated Variant Set</code> steuert die Generierung des <code>ECU Extract of System Description</code>. Fehlen Kriterien oder sind sie zirkulär definiert, scheitert die BSW-Codegenerierung (z. B. Can, Com, PduR) bereits im Schritt der Parameterextraktion.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4f09209a629bf232", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR Methodology Activity Diagram (SPEM-/UML-Profil der AUTOSAR-Methodik).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Prozessschritts <code>Define System Variants</code> (SPEM Task) innerhalb der Phase <em>System Configuration</em> der AUTOSAR-Methodik. Der Schritt dient der formalen Festlegung, Bindung und Konsolidierung von Produktlinien-Variabilitäten über Topologie, Signalrouting, SWC-Zuordnung und ECU-Konfigurationen hinweg vor dem <em>System Extract of System Description</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Aktivitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>System Engineer</code></strong> (Rolle): Verantwortlicher Entwickler/Rolle; führt die Aktivität aus (<code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li><strong><code>«SPEM_Ta... Define System Variants</code></strong> (Activity / Task): Zentraler Transformationsschritt zur Auflösung bzw. Deklaration von Systemvarianten, dargestellt als abgerundetes SPEM-Task-Symbol.\n</li></ul>\n<h5 class=\"fig-section-h5\">Eingangsartefakte (<code>«input»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>Topology</code></strong> (Kardinalität <code>1</code>): Physikalische Vernetzung, Busse (CAN, LIN, FlexRay, Ethernet) und Cluster.\n</li><li><strong><code>System Description</code></strong> (Kardinalität <code>0..*</code>): Übergeordnete Gesamtsystembeschreibung (im Diagramm verkürzt als <code>System</code> beschriftet).\n</li><li><strong><code>System Description Root Element</code></strong>: Wurzelknoten des System-Modells (<code>SYSTEM</code>-Metaklasse).\n</li><li><strong><code>Complete ECU Description</code></strong> (Kardinalität <code>1..*</code>): Vollständige Baukasten-Beschreibungen aller im System beteiligten Steuergeräte.\n</li><li><strong><code>Mapping of Software Components to ECUs</code></strong>: Zuweisung von atomaren SWC-Prototypen auf spezifische ECUs (im Diagramm verkürzt als <code>Mapping of Software</code> beschriftet).\n</li><li><strong><code>Mapping of Software Components to Implementations</code></strong>: Zuordnung der logischen SWCs zu konkreten C-/Objektcode-Implementierungen (<code>SwcImplementation</code>).\n</li><li><strong><code>System Signal</code></strong> &amp; <strong><code>System Signal Group</code></strong>: Kommunikationsmatrix-Elemente im Systemkontext (Signale und strukturierte Signalverbünde).\n</li><li><strong><code>System Timing</code></strong>: Globale und lokale Timing-Constraints (z. B. Latenzen, Event-Triggering).\n</li></ul>\n<h5 class=\"fig-section-h5\">Ein-/Ausgangs- und Ergebnisartefakte (<code>«output»</code> / <code>«inoutput»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>System Constant Value Set</code></strong> (<code>«inoutput»</code>): Iterativ definierte Belegung von Systemkonstanten (<code>SwSystemconst</code>), die als Prädikate in Variantenbedingungen dienen.\n</li><li><strong><code>Postbuild Variant Set</code></strong> (<code>«inoutput»</code>): Spezifikation der zur Post-Build-Zeit (Ladezeit/Initialisierungszeit) auflösbaren Variantenkriterien (<code>PostBuildVariantCriterion</code>).\n</li><li><strong><code>Predefined Variant</code></strong> (<code>«output»</code>): Deklaration vordefinierter Konfigurationszustände für Pre-Compile-Varianten durch Bündelung spezifischer <code>SystemConstantValueSets</code>.\n</li><li><strong><code>Evaluated Variant Set</code></strong> (<code>«output»</code>): Konsistenzgeprüfter und ausgewerteter Variantensatz zur Ableitung konkreter System- und ECU-Extrakte.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Eingangs-Aggregation:</strong> Einlesen der Systembeschreibungs-Fragmente (Topologie, SWC-Mappings, Signale, Timing und ECU-Beschreibungen).\n</li><li><strong>Kriterien-Definition &amp; Iteration (<code>«inoutput»</code>):</strong>\n<ul class=\"fig-list\"><li>Festlegung bzw. Aktualisierung von <code>System Constant Value Sets</code> zur statischen Konditionierung (<code>bindingTime = codeGenerationTime / preCompileTime</code>).\n</li><li>Definition bzw. Abgleich von <code>Postbuild Variant Sets</code> für dynamische Konfigurationen (<code>bindingTime = postBuild / runtime</code>).\n</li></ul>\n</li><li><strong>Varianten-Kombination (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li>Instanziierung von <code>Predefined Variant</code>-Elementen, die Gruppen von Systemkonstanten-Werten referenzieren.\n</li><li>Generierung des <code>Evaluated Variant Set</code>: Formal verifizierter Zustand, in dem alle <code>VariationPoint</code>-Elemente (z. B. an Signalmappings, Ports oder Verbindungen) widerspruchsfrei gegen die definierten Kriterien evaluierbar sind.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Rollenverantwortung:</strong> Die Variantenbindung erfordert zwingend die Domänenkompetenz des <code>System Engineer</code>, da Festlegungen Schnittstellen über mehrere Subsysteme und ECUs hinweg betreffen.\n</li><li><strong>Konsistenzprüfung:</strong> Das Zusammenspiel von <code>System Constant Value Set</code>, <code>Predefined Variant</code> und <code>Postbuild Variant Set</code> muss deterministisch und konfliktfrei aufgelöst werden, um ein valides <code>Evaluated Variant Set</code> für nachfolgende Prozessschritte bereitzustellen.\n</li><li><strong>Artefaktvollständigkeit:</strong> Sämtliche Mappings, Signale, Topologiebeschreibungen und ECU-Parameter müssen als konsistente Gesamtrepräsentation vorliegen, um unvollständige Variantenableitungen auszuschließen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4d06945ecfd2d86f", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR Methodology Activity Diagram (SPEM-/UML-Profil der AUTOSAR-Methodik).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Prozessschritts <code>Define System Variants</code> (SPEM Task) innerhalb der Phase <em>System Configuration</em> der AUTOSAR-Methodik. Der Schritt dient der formalen Festlegung, Bindung und Konsolidierung von Produktlinien-Variabilitäten über Topologie, Signalrouting, SWC-Zuordnung und ECU-Konfigurationen hinweg vor dem <em>System Extract of System Description</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Aktivitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>System Engineer</code></strong> (Rolle): Verantwortlicher Entwickler/Rolle; führt die Aktivität aus (<code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li><strong><code>«SPEM_Ta... Define System Variants</code></strong> (Activity / Task): Zentraler Transformationsschritt zur Auflösung bzw. Deklaration von Systemvarianten, dargestellt als abgerundetes SPEM-Task-Symbol.\n</li></ul>\n<h5 class=\"fig-section-h5\">Eingangsartefakte (<code>«input»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>Topology</code></strong> (Kardinalität <code>1</code>): Physikalische Vernetzung, Busse (CAN, LIN, FlexRay, Ethernet) und Cluster.\n</li><li><strong><code>System Description</code></strong> (Kardinalität <code>0..*</code>): Übergeordnete Gesamtsystembeschreibung (im Diagramm verkürzt als <code>System</code> beschriftet).\n</li><li><strong><code>System Description Root Element</code></strong>: Wurzelknoten des System-Modells (<code>SYSTEM</code>-Metaklasse).\n</li><li><strong><code>Complete ECU Description</code></strong> (Kardinalität <code>1..*</code>): Vollständige Baukasten-Beschreibungen aller im System beteiligten Steuergeräte.\n</li><li><strong><code>Mapping of Software Components to ECUs</code></strong>: Zuweisung von atomaren SWC-Prototypen auf spezifische ECUs (im Diagramm verkürzt als <code>Mapping of Software</code> beschriftet).\n</li><li><strong><code>Mapping of Software Components to Implementations</code></strong>: Zuordnung der logischen SWCs zu konkreten C-/Objektcode-Implementierungen (<code>SwcImplementation</code>).\n</li><li><strong><code>System Signal</code></strong> &amp; <strong><code>System Signal Group</code></strong>: Kommunikationsmatrix-Elemente im Systemkontext (Signale und strukturierte Signalverbünde).\n</li><li><strong><code>System Timing</code></strong>: Globale und lokale Timing-Constraints (z. B. Latenzen, Event-Triggering).\n</li></ul>\n<h5 class=\"fig-section-h5\">Ein-/Ausgangs- und Ergebnisartefakte (<code>«output»</code> / <code>«inoutput»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>System Constant Value Set</code></strong> (<code>«inoutput»</code>): Iterativ definierte Belegung von Systemkonstanten (<code>SwSystemconst</code>), die als Prädikate in Variantenbedingungen dienen.\n</li><li><strong><code>Postbuild Variant Set</code></strong> (<code>«inoutput»</code>): Spezifikation der zur Post-Build-Zeit (Ladezeit/Initialisierungszeit) auflösbaren Variantenkriterien (<code>PostBuildVariantCriterion</code>).\n</li><li><strong><code>Predefined Variant</code></strong> (<code>«output»</code>): Deklaration vordefinierter Konfigurationszustände für Pre-Compile-Varianten durch Bündelung spezifischer <code>SystemConstantValueSets</code>.\n</li><li><strong><code>Evaluated Variant Set</code></strong> (<code>«output»</code>): Konsistenzgeprüfter und ausgewerteter Variantensatz zur Ableitung konkreter System- und ECU-Extrakte.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Eingangs-Aggregation:</strong> Einlesen der Systembeschreibungs-Fragmente (Topologie, SWC-Mappings, Signale, Timing und ECU-Beschreibungen).\n</li><li><strong>Kriterien-Definition &amp; Iteration (<code>«inoutput»</code>):</strong>\n<ul class=\"fig-list\"><li>Festlegung bzw. Aktualisierung von <code>System Constant Value Sets</code> zur statischen Konditionierung (<code>bindingTime = codeGenerationTime / preCompileTime</code>).\n</li><li>Definition bzw. Abgleich von <code>Postbuild Variant Sets</code> für dynamische Konfigurationen (<code>bindingTime = postBuild / runtime</code>).\n</li></ul>\n</li><li><strong>Varianten-Kombination (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li>Instanziierung von <code>Predefined Variant</code>-Elementen, die Gruppen von Systemkonstanten-Werten referenzieren.\n</li><li>Generierung des <code>Evaluated Variant Set</code>: Formal verifizierter Zustand, in dem alle <code>VariationPoint</code>-Elemente (z. B. an Signalmappings, Ports oder Verbindungen) widerspruchsfrei gegen die definierten Kriterien evaluierbar sind.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Rollenverantwortung:</strong> Die Variantenbindung erfordert zwingend die Domänenkompetenz des <code>System Engineer</code>, da Festlegungen Schnittstellen über mehrere Subsysteme und ECUs hinweg betreffen.\n</li><li><strong>Konsistenzprüfung:</strong> Das Zusammenspiel von <code>System Constant Value Set</code>, <code>Predefined Variant</code> und <code>Postbuild Variant Set</code> muss deterministisch und konfliktfrei aufgelöst werden, um ein valides <code>Evaluated Variant Set</code> für nachfolgende Prozessschritte bereitzustellen.\n</li><li><strong>Artefaktvollständigkeit:</strong> Sämtliche Mappings, Signale, Topologiebeschreibungen und ECU-Parameter müssen als konsistente Gesamtrepräsentation vorliegen, um unvollständige Variantenableitungen auszuschließen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-54eb561574b965c8", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR Methodology Activity Diagram (SPEM-/UML-Profil der AUTOSAR-Methodik).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Prozessschritts <code>Define System Variants</code> innerhalb der Phase <em>System Configuration</em> der AUTOSAR-Methodik. Der Schritt dient der formalen Festlegung, Bindung und Konsolidierung von Produktlinien-Variabilitäten über Topologie, Signalrouting, SWC-Zuordnung und ECU-Konfigurationen hinweg vor dem <em>System Extract of System Description</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Aktivitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>System Engineer</code></strong> (Rolle): Verantwortlicher Entwickler/Rolle; führt die Aktivität aus (<code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li><strong><code>Define System Variants</code></strong> (Activity / Task): Zentraler Transformationsschritt zur Auflösung bzw. Deklaration von Systemvarianten, dargestellt als Aktivitätspfeil.\n</li></ul>\n<h5 class=\"fig-section-h5\">Eingangsartefakte (<code>«input»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>Topology</code></strong> (Kardinalität <code>1</code>): Physikalische Vernetzung, Busse und Cluster.\n</li><li><strong><code>System Description</code></strong> (Kardinalität <code>0..*</code>): Übergeordnete Gesamtsystembeschreibung, links im Diagramm positioniert.\n</li><li><strong><code>System Description Root Element</code></strong>: Wurzelknoten des System-Modells.\n</li><li><strong><code>Complete ECU Description</code></strong> (Kardinalität <code>1..*</code>): Vollständige Baukasten-Beschreibungen aller beteiligten Steuergeräte.\n</li><li><strong><code>Mapping of Software Components to ECUs</code></strong>: Zuweisung von SWC-Prototypen auf ECUs, oben links positioniert.\n</li><li><strong><code>Mapping of Software Components to Implementations</code></strong>: Zuordnung der logischen SWCs zu konkreten Implementierungen.\n</li><li><strong><code>System Signal</code></strong>: Kommunikationsmatrix-Signale.\n</li><li><strong><code>System Signal Group</code></strong>: Strukturierte Signalverbünde (im Diagramm unten verkürzt als <code>System</code> beschriftet).\n</li><li><strong><code>System Timing</code></strong>: Globale und lokale Timing-Constraints (im Diagramm unten verkürzt als <code>System</code> beschriftet).\n</li></ul>\n<h5 class=\"fig-section-h5\">Ein-/Ausgangs- und Ergebnisartefakte (<code>«output»</code> / <code>«inoutput»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>System Constant Value Set</code></strong> (<code>«inoutput»</code>): Iterativ definierte Belegung von Systemkonstanten (im Diagramm unten rechts verkürzt als <code>System Constant Val...</code> beschriftet).\n</li><li><strong><code>Postbuild Variant Set</code></strong> (<code>«inoutput»</code>): Spezifikation der zur Post-Build-Zeit auflösbaren Variantenkriterien.\n</li><li><strong><code>Predefined Variant</code></strong> (<code>«output»</code>): Deklaration vordefinierter Konfigurationszustände für Pre-Compile-Varianten.\n</li><li><strong><code>Evaluated Variant Set</code></strong> (<code>«output»</code>): Konsistenzgeprüfter und ausgewerteter Variantensatz zur Ableitung konkreter System- und ECU-Extrakte.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Eingangs-Aggregation:</strong> Einlesen der Systembeschreibungs-Fragmente (Topologie, SWC-Mappings, Signale, Timing und ECU-Beschreibungen).\n</li><li><strong>Kriterien-Definition &amp; Iteration (<code>«inoutput»</code>):</strong>\n<ul class=\"fig-list\"><li>Festlegung bzw. Aktualisierung von <code>System Constant Value Sets</code> zur statischen Konditionierung (<code>bindingTime = codeGenerationTime / preCompileTime</code>).\n</li><li>Definition bzw. Abgleich von <code>Postbuild Variant Sets</code> für dynamische Konfigurationen (<code>bindingTime = postBuild / runtime</code>).\n</li></ul>\n</li><li><strong>Varianten-Kombination (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li>Instanziierung von <code>Predefined Variant</code>-Elementen, die Gruppen von Systemkonstanten-Werten referenzieren.\n</li><li>Generierung des <code>Evaluated Variant Set</code>: Formal verifizierter Zustand, in dem alle <code>VariationPoint</code>-Elemente (z. B. an Signalmappings, Ports oder Verbindungen) widerspruchsfrei gegen die definierten Kriterien evaluierbar sind.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Rollenverantwortung:</strong> Die Variantenbindung erfordert zwingend die Domänenkompetenz des <code>System Engineer</code>, da Festlegungen Schnittstellen über mehrere Subsysteme und ECUs hinweg betreffen.\n</li><li><strong>Konsistenzprüfung:</strong> Das Zusammenspiel von <code>System Constant Value Set</code>, <code>Predefined Variant</code> und <code>Postbuild Variant Set</code> muss deterministisch und konfliktfrei aufgelöst werden, um ein valides <code>Evaluated Variant Set</code> für nachfolgende Prozessschritte bereitzustellen.\n</li><li><strong>Artefaktvollständigkeit:</strong> Sämtliche Mappings, Signale, Topologiebeschreibungen und ECU-Parameter müssen als konsistente Gesamtrepräsentation vorliegen, um unvollständige Variantenableitungen auszuschließen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-bd9eb12d1cf023a4", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR Methodology Activity Diagram (SPEM-/UML-Profil der AUTOSAR-Methodik).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Spezifikation des Prozessschritts <code>Define System Variants</code> innerhalb der Phase <em>System Configuration</em> der AUTOSAR-Methodik. Der Schritt dient der formalen Festlegung, Bindung und Konsolidierung von Produktlinien-Variabilitäten über Topologie, Signalrouting, SWC-Zuordnung und ECU-Konfigurationen hinweg vor dem <em>System Extract of System Description</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Akteure &amp; Aktivitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>System Engineer</code></strong> (Rolle): Verantwortlicher Entwickler/Rolle; führt die Aktivität aus (<code>«performs»</code>, Kardinalität <code>1</code>).\n</li><li><strong><code>Define System Variants</code></strong> (Activity / Task): Zentraler Transformationsschritt zur Auflösung bzw. Deklaration von Systemvarianten, dargestellt als Aktivitätspfeil.\n</li></ul>\n<h5 class=\"fig-section-h5\">Eingangsartefakte (<code>«input»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>Topology</code></strong> (Kardinalität <code>1</code>): Physikalische Vernetzung, Busse und Cluster.\n</li><li><strong><code>System Description</code></strong> (Kardinalität <code>0..*</code>): Übergeordnete Gesamtsystembeschreibung, links im Diagramm positioniert.\n</li><li><strong><code>System Description Root Element</code></strong>: Wurzelknoten des System-Modells.\n</li><li><strong><code>Complete ECU Description</code></strong> (Kardinalität <code>1..*</code>): Vollständige Baukasten-Beschreibungen aller beteiligten Steuergeräte.\n</li><li><strong><code>Mapping of Software Components to ECUs</code></strong>: Zuweisung von SWC-Prototypen auf ECUs, oben links positioniert.\n</li><li><strong><code>Mapping of Software Components to Implementations</code></strong>: Zuordnung der logischen SWCs zu konkreten Implementierungen.\n</li><li><strong><code>System Signal</code></strong>: Kommunikationsmatrix-Signale.\n</li><li><strong><code>System Signal Group</code></strong>: Strukturierte Signalverbünde (im Diagramm unten verkürzt als <code>System</code> beschriftet).\n</li><li><strong><code>System Timing</code></strong>: Globale und lokale Timing-Constraints (im Diagramm unten verkürzt als <code>System</code> beschriftet).\n</li></ul>\n<h5 class=\"fig-section-h5\">Ein-/Ausgangs- und Ergebnisartefakte (<code>«output»</code> / <code>«inoutput»</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>System Constant Value Set</code></strong> (<code>«inoutput»</code>): Iterativ definierte Belegung von Systemkonstanten (im Diagramm unten rechts verkürzt als <code>System Constant Val...</code> beschriftet).\n</li><li><strong><code>Postbuild Variant Set</code></strong> (<code>«inoutput»</code>): Spezifikation der zur Post-Build-Zeit auflösbaren Variantenkriterien.\n</li><li><strong><code>Predefined Variant</code></strong> (<code>«output»</code>): Deklaration vordefinierter Konfigurationszustände für Pre-Compile-Varianten.\n</li><li><strong><code>Evaluated Variant Set</code></strong> (<code>«output»</code>): Konsistenzgeprüfter und ausgewerteter Variantensatz zur Ableitung konkreter System- und ECU-Extrakte.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Eingangs-Aggregation:</strong> Einlesen der Systembeschreibungs-Fragmente (Topologie, SWC-Mappings, Signale, Timing und ECU-Beschreibungen).\n</li><li><strong>Kriterien-Definition &amp; Iteration (<code>«inoutput»</code>):</strong>\n<ul class=\"fig-list\"><li>Festlegung bzw. Aktualisierung von <code>System Constant Value Sets</code> zur statischen Konditionierung (<code>bindingTime = codeGenerationTime / preCompileTime</code>).\n</li><li>Definition bzw. Abgleich von <code>Postbuild Variant Sets</code> für dynamische Konfigurationen (<code>bindingTime = postBuild / runtime</code>).\n</li></ul>\n</li><li><strong>Varianten-Kombination (<code>«output»</code>):</strong>\n<ul class=\"fig-list\"><li>Instanziierung von <code>Predefined Variant</code>-Elementen, die Gruppen von Systemkonstanten-Werten referenzieren.\n</li><li>Generierung des <code>Evaluated Variant Set</code>: Formal verifizierter Zustand, in dem alle <code>VariationPoint</code>-Elemente (z. B. an Signalmappings, Ports oder Verbindungen) widerspruchsfrei gegen die definierten Kriterien evaluierbar sind.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Rollenverantwortung:</strong> Die Variantenbindung erfordert zwingend die Domänenkompetenz des <code>System Engineer</code>, da Festlegungen Schnittstellen über mehrere Subsysteme und ECUs hinweg betreffen.\n</li><li><strong>Konsistenzprüfung:</strong> Das Zusammenspiel von <code>System Constant Value Set</code>, <code>Predefined Variant</code> und <code>Postbuild Variant Set</code> muss deterministisch und konfliktfrei aufgelöst werden, um ein valides <code>Evaluated Variant Set</code> für nachfolgende Prozessschritte bereitzustellen.\n</li><li><strong>Artefaktvollständigkeit:</strong> Sämtliche Mappings, Signale, Topologiebeschreibungen und ECU-Parameter müssen als konsistente Gesamtrepräsentation vorliegen, um unvollständige Variantenableitungen auszuschließen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5659bd9555085cb2", "to": "FIG-4f09209a629bf232", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Aktivität <code>Define System Variants</code>: Die Form des Knotens wurde von einem nach rechts weisenden Pfeilsymbol (Action-Block) zu einem abgerundeten Rechteck mit SPEM-Stereotyp-Präfix <code>«SPEM_Ta... Define System Variants</code> geändert.\n</li><li>Beschriftung <code>Mapping of Software Components to ECUs</code>: Durch Zeilenumbruch bzw. Textabschneidung am unteren Rand auf <code>Mapping of Software</code> verkürzt dargestellt.\n</li><li>Beschriftung <code>System Description</code>: Am unteren Umschlag-Symbol auf <code>System</code> verkürzt dargestellt.\n</li></ul>"}, {"from": "FIG-4f09209a629bf232", "to": "FIG-4d06945ecfd2d86f", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4d06945ecfd2d86f", "to": "FIG-54eb561574b965c8", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Aktivität <code>Define System Variants</code>: Knotensymbol wieder als nach rechts gerichteter Aktivitätspfeil ohne SPEM-Stereotyppräfix dargestellt.\n</li><li>Eingangsartefakt <code>System Description</code>: Von der unteren Position an die linke Seite verschoben; die Beschriftung ist wieder vollständig als <code>System Description</code> sichtbar.\n</li><li>Eingangsartefakt <code>Mapping of Software Components to ECUs</code>: Von der unteren Position an die obere Kante verschoben; die Beschriftung ist wieder vollständig sichtbar.\n</li><li>Beschriftungsabschneidungen an den unteren Artefakten: Das zweite und dritte Dokumentensymbol am unteren Rand sind unvollständig mit <code>System</code> bzw. <code>System</code> beschriftet (<code>System Signal Group</code> und <code>System Timing</code>), ebenso das Symbol unten rechts mit <code>System Constant Val...</code>.\n</li><li>Layout und Anordnung: Umfangreiche Neuanordnung aller Artefaktknoten rund um die zentrale Aktivität.\n</li></ul>"}, {"from": "FIG-54eb561574b965c8", "to": "FIG-bd9eb12d1cf023a4", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
